mapper.select:
SELECT MAX(R.CX_BATCH_NO) CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ R.BIG_ROLL_CODE, /*帘线规格*/ R.CLOTH_CODE, /*胎体布代号*/ MAX(R.CRAFT) CRAFT, /*胎体布工艺*/ MAX(R.TIRE_FABRIC_SIDE_RUBBER) EDGE_GLUE, /*半钢边胶*/
SUM((nvl(R.CLASS1_PLAN_QTY, 0) + nvl(R.CLASS2_PLAN_QTY, 0)) * R.SIDEWALL_LENGTH / 1000) DAY_PLAN_QTY, /*中班计划量*/ SUM((nvl(R.CLASS3_PLAN_QTY, 0) + nvl(R.CLASS4_PLAN_QTY, 0)) * R.SIDEWALL_LENGTH / 1000) NIGHT_PLAN_QTY, /*夜班计划量*/ NVL(ROUND(AVG(R.SIDEWALL_LENGTH), 3), 0) UNIT_CONSUME, /*单耗*/ NVL(CEIL(SUM(R.CLASS1_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS1_PLAN, /*对应成型一班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS2_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS2_PLAN, /*对应成型二班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS3_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS3_PLAN, /*对应成型三班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS4_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS4_PLAN, /*对应成型次一班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS5_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS5_PLAN /*对应成型次二班的计划量，向上取整*/ FROM (SELECT R.CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ CI.TIRE_FABRIC_CODE1 CLOTH_CODE, /*1#胎体布代号*/ TRUNC(CI.TIRE_FABRIC_CRAFT1) CRAFT, /*1#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER , /*帘布边胶*/ NVL(CI.SIDEWALL_LENGTH, 0) SIDEWALL_LENGTH, /*单耗*/ NVL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, NVL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, NVL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, NVL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, NVL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
UNION ALL SELECT R.CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ CI.TIRE_FABRIC_CODE2 CLOTH_CODE, /*2#胎体布代号*/ TRUNC(CI.TIRE_FABRIC_CRAFT2) CRAFT, /*2#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER , /*帘布边胶*/ NVL(CI.SIDEWALL_LENGTH, 0) SIDEWALL_LENGTH, /*单耗*/ NVL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, NVL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, NVL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, NVL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, NVL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE2 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
UNION ALL SELECT R.CX_BATCH_NO, /*成型批次号*/ R.SCHEDULE_DATE, /*排产日期*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ CI.TIRE_FABRIC_CODE3 CLOTH_CODE, /*3#胎体布代号*/ TRUNC(CI.TIRE_FABRIC_CRAFT3) CRAFT, /*3#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER , /*帘布边胶*/ NVL(CI.SIDEWALL_LENGTH, 0) SIDEWALL_LENGTH, /*单耗*/ NVL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, NVL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, NVL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, NVL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, NVL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE3 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
) R GROUP BY R.SCHEDULE_DATE, R.BIG_ROLL_CODE, R.CLOTH_CODE
HAVING SUM((NVL(R.CLASS1_PLAN_QTY, 0) + NVL(R.CLASS2_PLAN_QTY, 0) + NVL(R.CLASS3_PLAN_QTY, 0) + NVL(R.CLASS4_PLAN_QTY, 0) + NVL(R.CLASS5_PLAN_QTY, 0)) * R.SIDEWALL_LENGTH) != 0 ORDER BY BIG_ROLL_CODE, CLOTH_CODE

WITH temp_tab_cloth_code AS (
SELECT #{schedule.clothCode} cloth_code FROM dual
) SELECT CASE WHEN MAX(CX_BATCH_NO) IS NULL THEN NVL(ROUND(MAX(UNIT_CONSUME), 3), 0) ELSE MAX(CASE WHEN CX_BATCH_NO IS NOT NULL THEN UNIT_CONSUME ELSE NULL END) END UNIT_CONSUME, /*当能关联上成型时需要按成型对应的版本取值，否则取最大值*/ MAX(BIG_ROLL_CODE) BIG_ROLL_CODE, MAX(CRAFT) CRAFT, /*工艺*/ MAX(TIRE_FABRIC_SIDE_RUBBER) EDGE_GLUE, /*半钢边胶*/ CLOTH_CODE, MAX(CX_BATCH_NO) CX_BATCH_NO, NVL(CEIL(SUM(R.CLASS1_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS1_PLAN, /*对应成型一班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS2_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS2_PLAN, /*对应成型二班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS3_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS3_PLAN, /*对应成型三班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS4_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS4_PLAN, /*对应成型次一班的计划量，向上取整*/ NVL(CEIL(SUM(R.CLASS5_PLAN_QTY * R.SIDEWALL_LENGTH / 1000)), 0) CX_CLASS5_PLAN /*对应成型次二班的计划量，向上取整*/ FROM ( SELECT CI.SIDEWALL_LENGTH UNIT_CONSUME /*单耗*/, CI.CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE1 CLOTH_CODE, TRUNC(CI.TIRE_FABRIC_CRAFT1) CRAFT, /*1#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER, /*帘布边胶*/ NVL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, NVL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, NVL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, NVL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, NVL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, R.CX_BATCH_NO, CI.SIDEWALL_LENGTH FROM T_PRODUCT_CONSTRUCTION_INFO CI LEFT JOIN T_CX_SCHEDULE_RESULT R ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION AND R.DEL_FLAG = '0' AND R.SCHEDULE_DATE = #{scheduleDate} WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IN ( SELECT cloth_code FROM temp_tab_cloth_code ) UNION SELECT CI.SIDEWALL_LENGTH UNIT_CONSUME /*单耗*/, CI.CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE2 CLOTH_CODE, TRUNC(CI.TIRE_FABRIC_CRAFT2) CRAFT, /*2#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER, /*帘布边胶*/ NVL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, NVL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, NVL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, NVL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, NVL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, R.CX_BATCH_NO, CI.SIDEWALL_LENGTH FROM T_PRODUCT_CONSTRUCTION_INFO CI LEFT JOIN T_CX_SCHEDULE_RESULT R ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION AND R.DEL_FLAG = '0' AND R.SCHEDULE_DATE = #{scheduleDate} WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE2 IN ( SELECT cloth_code FROM temp_tab_cloth_code ) UNION SELECT CI.SIDEWALL_LENGTH UNIT_CONSUME /*单耗*/, CI.CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE3 CLOTH_CODE, TRUNC(CI.TIRE_FABRIC_CRAFT3) CRAFT, /*3#胎体布工艺*/ CI.TIRE_FABRIC_SIDE_RUBBER, /*帘布边胶*/ NVL(R.CLASS1_PLAN_QTY, 0) CLASS1_PLAN_QTY, NVL(R.CLASS2_PLAN_QTY, 0) CLASS2_PLAN_QTY, NVL(R.CLASS3_PLAN_QTY, 0) CLASS3_PLAN_QTY, NVL(R.CLASS4_PLAN_QTY, 0) CLASS4_PLAN_QTY, NVL(R.CLASS5_PLAN_QTY, 0) CLASS5_PLAN_QTY, R.CX_BATCH_NO, CI.SIDEWALL_LENGTH FROM T_PRODUCT_CONSTRUCTION_INFO CI LEFT JOIN T_CX_SCHEDULE_RESULT R ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION AND R.DEL_FLAG = '0' AND R.SCHEDULE_DATE = #{scheduleDate} WHERE CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE3 IN ( SELECT cloth_code FROM temp_tab_cloth_code ) ) R GROUP BY CLOTH_CODE

mapper.insert:
INSERT INTO T_CD90_schedule_RESULT (ID, schedule_DATE, CX_BATCH_NO, BATCH_NO, ORDER_NO, BIG_ROLL_CODE, MACHINE_ID, CLOTH_CODE, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, DAY_PLAN_QTY, DAY_FINISH_QTY, DAY_FINISH_RATE, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_FINISH_QTY, NIGHT_FINISH_RATE, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, PUBLISH_SUCCESS_COUNT, NEWEST_PUBLISH_TIME, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, CLOSE_OUT_SPEC_FLAG, DATA_SOURCE, CRAFT, EDGE_GLUE, REMARK, DEL_FLAG, CREATE_BY, CREATE_TIME) SELECT SEQ_CD90_schedule.NEXTVAL AS ID, T.* FROM (
SELECT #{schedule.scheduleDate}, #{schedule.cxBatchNo,jdbcType = VARCHAR}, #{schedule.batchNo,jdbcType = VARCHAR}, #{schedule.orderNo,jdbcType = VARCHAR}, #{schedule.bigRollCode,jdbcType = VARCHAR}, #{schedule.machineId,jdbcType = VARCHAR}, #{schedule.clothCode,jdbcType = VARCHAR}, #{schedule.unitConsume,jdbcType = VARCHAR}, #{schedule.stockQty,jdbcType = DOUBLE}, #{schedule.supplyTime,jdbcType = DOUBLE}, #{schedule.dayPlanQty,jdbcType = DOUBLE}, #{schedule.dayFinishQty,jdbcType = DOUBLE}, #{schedule.dayFinishRate,jdbcType = DOUBLE}, #{schedule.dayProduceOrder,jdbcType = DOUBLE}, #{schedule.daySysAnalysis,jdbcType = VARCHAR}, #{schedule.dayHandAnalysis,jdbcType = VARCHAR}, #{schedule.nightPlanQty,jdbcType = DOUBLE}, #{schedule.nightFinishQty,jdbcType = DOUBLE}, #{schedule.nightFinishRate,jdbcType = DOUBLE}, #{schedule.nightProduceOrder,jdbcType = DOUBLE}, #{schedule.nightSysAnalysis,jdbcType = VARCHAR}, #{schedule.nightHandAnalysis,jdbcType = VARCHAR}, #{schedule.cxClass1Plan,jdbcType = DOUBLE}, #{schedule.cxClass2Plan,jdbcType = DOUBLE}, #{schedule.cxClass3Plan,jdbcType = DOUBLE}, #{schedule.cxClass4Plan,jdbcType = DOUBLE}, #{schedule.cxClass5Plan,jdbcType = DOUBLE}, #{schedule.isRelease,jdbcType = VARCHAR}, #{schedule.publishSuccessCount,jdbcType = INTEGER}, #{schedule.newestPublishTime,jdbcType = DATE}, #{schedule.markCloseOutTip,jdbcType = VARCHAR}, #{schedule.productionStatus,jdbcType = VARCHAR}, #{schedule.closeOutSpecFlag,jdbcType = VARCHAR}, #{schedule.dataSource,jdbcType = VARCHAR}, #{schedule.craft,jdbcType = VARCHAR}, #{schedule.edgeGlue,jdbcType = VARCHAR}, #{schedule.remark,jdbcType = VARCHAR}, #{schedule.delFlag,jdbcType = VARCHAR}, #{schedule.createBy,jdbcType = VARCHAR}, #{schedule.createTime} FROM DUAL
) T

mapper.update:
UPDATE T_CD90_AUTO_SCHEDULE_RECORD 
   SET DEL_FLAG = '1', 
       UPDATE_BY = #{createBy}, 
       UPDATE_TIME = #{createTime}
 WHERE schedule_date = #{scheduleDate}
   AND DEL_FLAG = '0'

MERGE INTO T_CD90_SCHEDULE_RESULT a USING (
SELECT #{schedule.scheduleDate} schedule_Date, #{schedule.cxBatchNo,jdbcType = VARCHAR} CX_BATCH_NO, #{schedule.batchNo,jdbcType = VARCHAR} BATCH_NO, #{schedule.orderNo,jdbcType = VARCHAR} order_No, #{schedule.bigRollCode,jdbcType = VARCHAR} big_Roll_Code, #{schedule.machineId,jdbcType = VARCHAR} machine_Id, #{schedule.clothCode,jdbcType = VARCHAR} cloth_code, #{schedule.unitConsume,jdbcType = DOUBLE} unit_Consume, #{schedule.stockQty,jdbcType = DOUBLE} stock_Qty, #{schedule.supplyTime,jdbcType = DOUBLE} supply_Time, #{schedule.dayPlanQty,jdbcType = DOUBLE} day_Plan_Qty, #{schedule.dayProduceOrder,jdbcType = DOUBLE} day_Produce_Order, #{schedule.dayHandAnalysis,jdbcType = VARCHAR} day_Hand_Analysis, #{schedule.nightPlanQty,jdbcType = DOUBLE} night_Plan_Qty, #{schedule.nightProduceOrder,jdbcType = DOUBLE} night_Produce_Order, #{schedule.nightHandAnalysis,jdbcType = VARCHAR} night_Hand_Analysis, #{schedule.cxClass1Plan,jdbcType = DOUBLE} CX_CLASS1_PLAN, #{schedule.cxClass2Plan,jdbcType = DOUBLE} CX_CLASS2_PLAN, #{schedule.cxClass3Plan,jdbcType = DOUBLE} CX_CLASS3_PLAN, #{schedule.cxClass4Plan,jdbcType = DOUBLE} CX_CLASS4_PLAN, #{schedule.cxClass5Plan,jdbcType = DOUBLE} CX_CLASS5_PLAN, #{schedule.isRelease,jdbcType = VARCHAR} is_Release, #{schedule.markCloseOutTip,jdbcType = VARCHAR} mark_Close_Out_Tip, #{schedule.craft,jdbcType = VARCHAR} CRAFT, #{schedule.edgeGlue,jdbcType = VARCHAR} EDGE_GLUE, #{schedule.remark,jdbcType = VARCHAR} remark, #{schedule.productionStatus,jdbcType = VARCHAR} production_Status, #{schedule.delFlag,jdbcType = VARCHAR} del_Flag, #{schedule.createBy,jdbcType = VARCHAR} create_By, #{schedule.createTime} create_Time, #{schedule.dataSource,jdbcType = VARCHAR} data_source from dual
) b ON (a.schedule_date = b.schedule_date AND a.big_Roll_Code = b.big_Roll_Code AND a.CLOTH_CODE = b.CLOTH_CODE AND a.machine_id = b.machine_id AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.stock_Qty = b.stock_Qty, a.day_Plan_Qty = b.day_Plan_Qty, a.night_Plan_Qty = b.night_Plan_Qty, a.day_Hand_Analysis = b.day_Hand_Analysis, a.night_Hand_Analysis = b.night_Hand_Analysis, a.mark_Close_Out_Tip = b.mark_Close_Out_Tip, a.remark = b.remark, a.production_status = b.production_status, a.update_by = b.create_By, a.update_time = b.create_Time, a.data_source = b.data_source, a.CX_CLASS1_PLAN = b.CX_CLASS1_PLAN, a.CX_CLASS2_PLAN = b.CX_CLASS2_PLAN, a.CX_CLASS3_PLAN = b.CX_CLASS3_PLAN, a.CX_CLASS4_PLAN = b.CX_CLASS4_PLAN, a.CX_CLASS5_PLAN = b.CX_CLASS5_PLAN, a.craft = b.craft, a.EDGE_GLUE = b.EDGE_GLUE, a.day_Produce_Order = b.day_Produce_Order, a.night_Produce_Order = b.night_Produce_Order WHEN NOT MATCHED THEN INSERT (a.id,a.schedule_Date,a.CX_BATCH_NO,a.batch_no,a.order_no,a.big_Roll_Code,a.machine_Id,a.cloth_code,a.unit_Consume,a.supply_time,a.stock_Qty,a.day_Plan_Qty,a.day_Produce_Order,a.day_Hand_Analysis,a.night_Plan_Qty,a.night_Produce_Order,a.night_Hand_Analysis,a.is_release,a.mark_close_out_tip,a.remark,a.production_status,a.del_flag,a.create_by,a.create_time,a.data_source,a.CX_CLASS1_PLAN,a.CX_CLASS2_PLAN,a.CX_CLASS3_PLAN,a.CX_CLASS4_PLAN,a.CX_CLASS5_PLAN,a.CRAFT,a.EDGE_GLUE) values (SEQ_CD90_SCHEDULE.NEXTVAL,b.schedule_Date,b.CX_BATCH_NO,b.batch_no,b.order_no,b.big_Roll_Code,b.machine_Id,b.cloth_code,b.unit_Consume,b.supply_time,b.stock_Qty,b.day_Plan_Qty,b.day_Produce_Order,b.day_Hand_Analysis,b.night_Plan_Qty,b.night_Produce_Order,b.night_Hand_Analysis,b.is_release,b.mark_close_out_tip,b.remark,b.production_status,b.del_flag,b.create_by,b.create_time,b.data_source,b.CX_CLASS1_PLAN,b.CX_CLASS2_PLAN,b.CX_CLASS3_PLAN,b.CX_CLASS4_PLAN,b.CX_CLASS5_PLAN,b.CRAFT,b.EDGE_GLUE)

MERGE INTO T_CD90_SCHEDULE_RESULT a USING (
SELECT #{schedule.dayPlanQty,jdbcType = DOUBLE} day_Plan_Qty, #{schedule.dayProduceOrder,jdbcType = DOUBLE} day_Produce_Order, #{schedule.nightPlanQty,jdbcType = DOUBLE} night_Plan_Qty, #{schedule.nightProduceOrder,jdbcType = DOUBLE} night_Produce_Order, #{schedule.isRelease,jdbcType = VARCHAR} is_Release, #{schedule.updateBy,jdbcType = VARCHAR} update_by, #{schedule.updateTime} update_time, #{schedule.id} id from dual
) b ON (a.id = b.id) WHEN MATCHED THEN UPDATE SET a.day_Plan_Qty = b.day_Plan_Qty, a.day_Produce_Order = b.day_Produce_Order, a.night_Plan_Qty = b.night_Plan_Qty, a.night_Produce_Order = b.night_Produce_Order, a.is_Release = b.is_Release, a.update_by = b.update_by, a.update_time = b.update_time

mapper.insert:
INSERT INTO T_CD90_ASSIST_schedule (ID, schedule_DATE, CX_BATCH_NO, BATCH_NO, ORDER_NO, BIG_ROLL_CODE, MACHINE_ID, CLOTH_CODE, UNIT_CONSUME, STOCK_QTY, SUPPLY_TIME, DAY_PLAN_QTY, DAY_PRODUCE_ORDER, DAY_SYS_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_PRODUCE_ORDER, NIGHT_SYS_ANALYSIS, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, DEL_FLAG, CREATE_BY, CREATE_TIME) SELECT SEQ_CD90_schedule.NEXTVAL AS ID, T.* FROM (
SELECT #{schedule.scheduleDate}, #{schedule.cxBatchNo,jdbcType = VARCHAR}, #{schedule.batchNo,jdbcType = VARCHAR}, #{schedule.orderNo,jdbcType = VARCHAR}, #{schedule.bigRollCode,jdbcType = VARCHAR}, #{schedule.machineId,jdbcType = VARCHAR}, #{schedule.clothCode,jdbcType = VARCHAR}, #{schedule.unitConsume,jdbcType = VARCHAR}, #{schedule.stockQty,jdbcType = DOUBLE}, #{schedule.supplyTime,jdbcType = DOUBLE}, #{schedule.dayPlanQty,jdbcType = DOUBLE}, #{schedule.dayProduceOrder,jdbcType = DOUBLE}, #{schedule.daySysAnalysis,jdbcType = VARCHAR}, #{schedule.nightPlanQty,jdbcType = DOUBLE}, #{schedule.nightProduceOrder,jdbcType = DOUBLE}, #{schedule.nightSysAnalysis,jdbcType = VARCHAR}, #{schedule.cxClass1Plan,jdbcType = DOUBLE}, #{schedule.cxClass2Plan,jdbcType = DOUBLE}, #{schedule.cxClass3Plan,jdbcType = DOUBLE}, #{schedule.cxClass4Plan,jdbcType = DOUBLE}, #{schedule.cxClass5Plan,jdbcType = DOUBLE}, #{schedule.isRelease,jdbcType = VARCHAR}, #{schedule.markCloseOutTip,jdbcType = VARCHAR}, #{schedule.productionStatus,jdbcType = VARCHAR}, #{schedule.delFlag,jdbcType = VARCHAR}, #{schedule.createBy,jdbcType = VARCHAR}, #{schedule.createTime} FROM DUAL
) T
